import{z as n,x as o,o as A,c as d,q as B,j as l,D as e,d as a,s,S as r,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"多样性的度量与覆盖","description":"","frontmatter":{"title":"多样性的度量与覆盖","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-diversity-metrics.md","filePath":"llm/synthetic-diversity-metrics.md","lastUpdated":1791063341000}'),m={name:"llm/synthetic-diversity-metrics.md"};function p(D,E,c,h,u,f){const i=o("Mermaid");return A(),d("div",null,[E[2]||(E[2]=B('<h1 id="多样性的度量与覆盖" tabindex="-1">多样性的度量与覆盖 <a class="header-anchor" href="#多样性的度量与覆盖" aria-label="Permalink to &quot;多样性的度量与覆盖&quot;">​</a></h1><div class="epigraph"><p>多样性从来不是「越大越好」的标量，是相对目标分布的覆盖率：没有真实锚点，连「多样」两个字都无从谈起。</p><footer>—— 据 Liu 等 DEITA；Zhou 等 LIMA；本站数据飞轮课整理</footer></div><p><a href="/llm/synthetic-difficulty-curriculum">上一课</a>控制了「梯度在哪」，本课控制「覆盖多大」。多样性收缩是自训练回路的系统性损耗：<a href="/llm/self-improvement-loop">自改进回路的解剖</a>把它列为损耗之首，<a href="/llm/data-flywheel-stop">数据飞轮的停止条件</a>给了三个仪表。本课把「多样性」拆成可度量的层级，写每个层级能被怎样骗过、该配什么审计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多样性的度量难点在「表面多样、语义单一」的分离。让教师把同一道题换二十种措辞，distinct-n 仍然很高，嵌入空间里却是二十个几乎重合的点；反过来，语义去重的阈值设松了，会把真正不同的任务误判为同义。更深的缺口是覆盖没有定义域：说「数据更多样」必须回答「相对什么更多样」——相对真实用户查询、相对基准题型网格、还是相对能力清单。没有目标分布，多样性只是生成温度的函数；有了目标分布，它才是配比可以优化的对象。<span class="marginnote">术语翻译：distinct-n 是统计「不同 n-gram（连续 n 个词的片段）占比」的指标，占比高说明字面用词丰富。但它完全不看意思——同一道题换个说法就能骗过它，所以它只配当报警器，不配当审计员。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四层度量，逐层到语义。表面层：distinct-n、自重复率、模板骨架熵——便宜、每日可跑、最易被骗，只配做报警不做结论。语义层：样本过嵌入器，看簇数、簇间质心距离、k 近邻平均距离，与<a href="/llm/semdedup">语义去重</a>的聚类直接复用；指令侧可用<a href="/llm/instruction-embeddings">指令嵌入</a>的专用编码器。任务层：题型与能力网格的覆盖审计——把目标分布画成格子（任务族乘难度乘格式），统计每格占比，空白格与超重格点名。锚点层：抽样与真实查询分布对齐比较——覆盖真实分布的多少格、分布距离随批次移动的方向，这是唯一能回答「覆盖够不够」的一层。</p><p>生成侧的旋钮按层级对应：表面多样性调温度与去重阈值；语义多样性调种子池与提示变体；覆盖缺口靠定向合成补——对空白格定点出题，而不是全局升温。</p>',8)),(A(),l(r,null,{default:e(()=>[s(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E7%94%9F%E6%88%90%E6%89%B9%E6%AC%A1%22%5D%20--%3E%20SURF%5B%22%E8%A1%A8%E9%9D%A2%E5%B1%82%EF%BC%9Adistinct-n%20%E4%B8%8E%E9%AA%A8%E6%9E%B6%E7%86%B5%22%5D%0A%20%20SURF%20--%3E%20EMB%5B%22%E8%AF%AD%E4%B9%89%E5%B1%82%EF%BC%9A%E7%B0%87%E6%95%B0%E4%B8%8E%E8%BF%91%E9%82%BB%E8%B7%9D%E7%A6%BB%22%5D%0A%20%20EMB%20--%3E%20GRID%7B%22%E7%BD%91%E6%A0%BC%E8%A6%86%E7%9B%96%E5%AE%A1%E8%AE%A1%22%7D%0A%20%20GRID%20--%3E%7C%E7%A9%BA%E7%99%BD%E6%A0%BC%7C%20TARGET%5B%22%E5%AE%9A%E5%90%91%E5%90%88%E6%88%90%E8%A1%A5%E6%A0%BC%22%5D%0A%20%20GRID%20--%3E%7C%E8%B6%85%E9%87%8D%E6%A0%BC%7C%20DOWN%5B%22%E9%99%8D%E6%9D%83%E6%88%96%E5%8E%BB%E9%87%8D%E6%94%B6%E7%B4%A7%22%5D%0A%20%20GRID%20--%3E%7C%E6%AD%A3%E5%B8%B8%7C%20ANCH%5B%22%E4%B8%8E%E7%9C%9F%E5%AE%9E%E5%88%86%E5%B8%83%E5%AF%B9%E9%BD%90%E6%AF%94%E8%BE%83%22%5D%0A%20%20ANCH%20--%3E%20OUT%5B%22%E8%A6%86%E7%9B%96%E6%8A%A5%E5%91%8A%E5%85%A5%E5%BA%93%22%5D%0A%20%20TARGET%20--%3E%20GEN%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,[a("为什么表面层会被骗：措辞熵与任务熵是两个自由度，教师在措辞上均匀采样不费任何能力，而在任务上展开需要它真的会别的任务——所以坍缩最先发生在任务层，表面层最后才见底。这也是为什么熵与新颖占比是坍缩的先行指标："),t("a",{href:"/llm/model-collapse-empirics"},"模型坍缩的实证"),a("的监测口径里，生成分布熵与尾部占比的掉头早于平均质量的掉头。定向补格之所以优于全局升温：升温同时抬高所有格的方差，已超重的格更超重；定点出题把生成预算对准空白格，让多样性成为可执行的生产计划而不是统计副作用。锚点层是防自欺的最后一道：池内网格再满，也可能整体偏离真实分布——覆盖报告必须同时给池内占比与对真实分布的相对位置。")],-1)),(A(),l(r,null,{default:e(()=>[s(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E9%81%93%E9%A2%98%22%5D%20--%3E%20W%5B%22%E6%8E%AA%E8%BE%9E%E5%B1%82%3A%20%E6%8D%A2%2020%20%E7%A7%8D%E8%AF%B4%E6%B3%95%22%5D%0A%20%20W%20--%3E%20S1%5B%22distinct-n%20%E9%AB%98%2C%20%E5%B5%8C%E5%85%A5%E7%82%B9%E5%87%A0%E4%B9%8E%E9%87%8D%E5%90%88%22%5D%0A%20%20S1%20--%3E%20F%5B%22%E8%A1%A8%E9%9D%A2%E5%B1%82%E8%A2%AB%E9%AA%97%3A%20%E6%8A%A5%E5%91%8A%E6%98%BE%E7%A4%BA%E5%BE%88%E5%A4%9A%E6%A0%B7%22%5D%0A%20%20Q%20--%3E%20T%5B%22%E4%BB%BB%E5%8A%A1%E5%B1%82%3A%20%E6%8D%A2%E6%88%90%E4%B8%8D%E5%90%8C%E4%BB%BB%E5%8A%A1%E6%97%8F%22%5D%0A%20%20T%20--%3E%20S2%5B%22%E7%B0%87%E6%95%B0%E4%B8%8E%E8%B4%A8%E5%BF%83%E8%B7%9D%E7%A6%BB%E7%9C%9F%E7%9A%84%E5%8F%98%E5%A4%A7%22%5D%0A%20%20S2%20--%3E%20G%5B%22%E4%BB%BB%E5%8A%A1%E7%BD%91%E6%A0%BC%E5%87%BA%E7%8E%B0%E6%96%B0%E7%9A%84%E6%A0%BC%E5%AD%90%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p><span class="marginnote">数字实例：一批 1000 条数据，distinct-2 高达 0.98、表面层全绿；嵌入聚类后却只有 12 个簇、九成样本挤在 3 个簇里——语义层红灯。只看表面层会得出「数据很多样」的错误结论，审计必须逐层下钻。</span></p><p><span class="marginnote">distinct-n 对换皮完全不设防：同一模板改写二十遍，distinct-n 照样漂亮。多样性审计至少要到嵌入层，且嵌入器要定期换尺复核——教师亲生的嵌入器会把自家风格判为「多样」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>嵌入器的偏置决定语义层的上限：簇结构反映嵌入器的归纳偏好，不全是数据的结构，换嵌入器复核是纪律不是优化。覆盖目标分布本身需要一份真实查询或任务的样本——冷启动域没有锚点，此时覆盖报告只能给池内相对值，结论要降级。定向补格有过拟合到网格定义的风险：格子怎么切，模型就朝怎么切的方向学，网格设计要留余量并定期修订。最后，多样性与质量在预算上互斥：两端都要时，先看难度与覆盖的报告再定过滤器松紧，不要凭手感调阈值。<span class="marginnote">直觉类比：全局升温像把整间屋的灯一起调亮——原来刺眼的角落更刺眼，该亮的角落还是照不到；定向补格像拿手电筒去照空白格。生成预算就是电费，定点照明便宜且有效。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四层度量：表面、语义、任务网格、真实分布锚点；表面层只配报警。</li><li>坍缩先发生在任务层：生成熵与新颖占比是先行指标。</li><li>覆盖缺口用定向合成补，不用全局升温。</li><li>嵌入器要换尺复核，防教师自家风格被判为多样。</li><li>没有真实锚点的域，覆盖结论降级为池内相对值。</li><li>出处：Liu 等 DEITA 2023；Zhou 等 LIMA 2023；Shumailov 等 2024 的监测口径。</li></ul>',6))])}const T=n(m,[["render",p]]);export{_ as __pageData,T as default};
